import{_t as e,it as t,n,rt as r}from"./chunks/framework.C5Z6qjff.js";var i=JSON.parse(`{"title":"What OEA is","description":"","frontmatter":{"title":"What OEA is","covers":{"screens":[],"stories":[]}},"headers":[],"relativePath":"introduction/index.md","filePath":"introduction/index.md"}`),a={name:`introduction/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="what-oea-is" tabindex="-1">What OEA is <a class="header-anchor" href="#what-oea-is" aria-label="Permalink to “What OEA is”">​</a></h1><p>OEA – Open Enterprise Architecture – is an open-source tool for enterprise architecture management. You use it to capture the components of your organization&#39;s architecture (applications, data, technology), describe them with the properties your organization needs, and look at them in tables and, later, in diagrams and dashboards.</p><h2 id="editions" tabindex="-1">Editions <a class="header-anchor" href="#editions" aria-label="Permalink to “Editions”">​</a></h2><ul><li><strong>Community Edition</strong>: open source under the GNU Affero General Public License 3.0 (AGPL-3.0)</li><li><strong>Enterprise Edition</strong>: the same core with additional functions under a proprietary license</li></ul><p>This manual describes the Community Edition.</p><h2 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to “Concepts”">​</a></h2><p><strong>Metamodel</strong> : The types of things your repository contains (<em>entity types</em>, for example <em>Application Component</em> or <em>Data Object</em>) and their properties. A new instance starts without entity types; you import a starter package or your own metamodel package.</p><p><strong>Entity</strong> : One element of the architecture, for example the application <em>CRM System</em>. Every entity belongs to an entity type and carries values for its properties. Every change creates a new version.</p><p><strong>Catalog</strong> : A reusable table view of the repository. A catalog shows the entities of one entity type as rows; you sort and page through them.</p><p><strong>Roles and permissions</strong> : What a person may do depends on the permissions of their roles. Roles are granted through the groups of your identity provider.</p><h2 id="what-the-current-version-offers" tabindex="-1">What the current version offers <a class="header-anchor" href="#what-the-current-version-offers" aria-label="Permalink to “What the current version offers”">​</a></h2><p>This manual describes the development state of OEA. It contains the functions that are implemented:</p><ul><li>installing an instance and setting up its first administrator</li><li>connecting an identity provider (OpenID Connect) and granting roles through its groups</li><li>importing the starter configuration and metamodel packages</li><li>logging in with the identity provider or the local system admin account, with a second factor</li><li>creating catalogs and viewing their entities</li><li>writing entities in batch through the API</li></ul><div class="info custom-block"><p class="custom-block-title">Web interface</p><p>In this development state, the web interface runs in the development environment of the repository (<code>scripts/dev.sh</code>, see the <a href="https://github.com/open-enterprise-architecture/OEA/blob/main/docs/development.md" target="_blank" rel="noreferrer">development guide</a>). The operator setup of <a href="./../setup/installation">Installation</a> provides the API; all functions of this manual are also available through the <a href="./../api/">API</a>.</p><p>The screenshots of this manual are taken automatically from that environment with its sample data (instance <code>acme</code>, users of the development realm).</p></div>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};